import {cards,relics,canStep,options,apply,damage,fresh} from './rules.mjs?v=4';
export const REPORT_VERSION=1,RULES_VERSION='raid-rules-2026-10-15-v1';
const CAMPAIGN_RULES_VERSION='raid-rules-2026-10-16-v2';
const rulesVersion=s=>s.campaign?CAMPAIGN_RULES_VERSION:RULES_VERSION;
const keys=['v','screen','phase','turn','ap','hp','friendHp','rescue','guards','alarm','progress','loot','lootLost','strikeTurns','pin','block','friendBlock','assist','ready','queue','outcome','log','campaign','encounter','relic','encounterResults'];
export const snapshot=s=>Object.fromEntries(keys.filter(k=>Object.hasOwn(s,k)).map(k=>[k,structuredClone(s[k])]));
const same=(a,b)=>JSON.stringify(snapshot(a))===JSON.stringify(snapshot(b));
export function availableActions(s){if(s.screen==='reward')return Object.keys(relics).map(relic=>({type:'relic',relic}));if(s.screen!=='play')return [];return [...s.ready.flatMap(id=>options(s,id).map(o=>({type:'play',card:id,target:o.target}))),...(canStep(s)?[{type:'step'}]:[]),...(s.phase==='strike'?[{type:'retreat'}]:[]),...((s.phase==='retreat'||s.phase==='duel')&&s.loot?[{type:'drop'}]:[]),...(s.assist?[{type:'assist',target:'move'},{type:'assist',target:'block'}]:[]),{type:'end'}];}
export function actionLabel(a,before){if(a.type==='relic')return 'اخترت الأثر: '+(relics[a.relic]?.name||a.relic);if(a.type==='play'){const o=options(before,a.card).find(x=>x.target===a.target);return `${cards[a.card]?.name||a.card}: ${o?.label||a.target}`;}return {step:'تقدّم خطوة بلا بطاقة',end:'إنهاء الدور',retreat:'بدء الانسحاب',drop:'ترك الغنيمة',assist:a.target==='move'?'مساندة الرفيق: خطوة':'مساندة الرفيق: حماية',start:'بدء الغارة'}[a.type]||a.type;}
export function beginReport(s,{tutorial=false,now=new Date().toISOString()}={}){const complete=same(s,{...fresh(!!s.campaign),screen:'play'});return {schemaVersion:REPORT_VERSION,rulesVersion:rulesVersion(s),runId:globalThis.crypto?.randomUUID?.()||`run-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,recordingStartedAt:now,startedAt:complete?now:null,endedAt:null,coverage:complete?'complete':'partial',coverageNote:complete?null:'Recording began after this run had already started. Earlier decisions are unavailable.',tutorial,initial:snapshot(s),events:[],final:snapshot(s)};}
export function restoreReport(value,s){try{if(value?.schemaVersion===REPORT_VERSION&&value.rulesVersion===rulesVersion(s)&&Array.isArray(value.events)&&same(value.final,s)){const initial=value.initial;let last=initial;for(const e of value.events){if(!same(last,e.before)||!same(apply(e.before,e.action),e.after))throw Error('Invalid replay');last=e.after;}if(!same(last,s))throw Error('Incomplete replay');return value;}}catch{}return beginReport(s);}
export function recordAction(report,before,a,after,now=new Date().toISOString()){if(same(before,after))return report;if(!report||!same(report.final,before))report=beginReport(before);const alternatives=availableActions(before).map(action=>{const n=apply(before,action);return {action,label:actionLabel(action,before),after:snapshot(n),incomingDamage:n.screen==='play'?damage(n):0};});const event={index:report.events.length+1,at:now,action:structuredClone(a),label:actionLabel(a,before),before:snapshot(before),after:snapshot(after),incomingBefore:damage(before),incomingAfter:after.screen==='play'?damage(after):0,available:alternatives};return {...report,events:[...report.events,event],final:snapshot(after),endedAt:after.screen==='end'?now:report.endedAt};}
export function metrics(r){let damageTaken=0,unusedActions=0,peakAlarm=r.initial.alarm;const cardPlays=Object.fromEntries(Object.keys(cards).map(id=>[id,0]));for(const e of r.events){damageTaken+=Math.max(0,e.before.hp-e.after.hp);peakAlarm=Math.max(peakAlarm,e.after.alarm);if(e.action.type==='end')unusedActions+=e.before.ap;if(e.action.type==='play')cardPlays[e.action.card]++;}return {recordedDecisions:r.events.length,recordedDamageTaken:damageTaken,unusedActionsAtTurnEnd:unusedActions,peakAlarm,cardPlays,...(r.initial.campaign?{relicChosen:r.events.find(e=>e.action.type==='relic')?.action.relic??null,encounterResults:r.final.encounterResults,encounterReached:r.final.encounter}:{}),firstLootAtDecision:r.events.find(e=>!e.before.loot&&e.after.loot)?.index??null,companionFreedAtDecision:r.events.find(e=>e.before.rescue<3&&e.after.rescue>=3)?.index??null};}
export function exportReport(r){return {...r,game:'Al-Shanfara: The Way Back',build:r.initial.campaign?'raid-ui-v4-two-encounters':'raid-ui-v3-report-v1',cardDefinitions:cards,...(r.initial.campaign?{relicDefinitions:relics,campaignRules:{rulePrecedence:'These campaign rules and the selected relic override conflicting baseline single-encounter rules.',encounters:2,intermission:'After surviving the first encounter, choose exactly one relic. Heal up to 6 HP (cap 16), reset alarm to 1, ready all six cards; loot and companion outcome carry forward.',secondEncounter:'The pass guardian starts at strength 8. Win by reducing it to 0 or reaching 6 movement progress. Damage base is 1+ceil(guards/2). Loot slows Run to 2. No carrier or rescue objective in encounter 2.',relics:{recovery:'Recover first two waiting cards at end turn.',wind:'Run costs 0 actions, still enters FIFO queue.',blade:'Knife remains ready after each use, still costs 1 action; guard attacks still cost 1 HP.'}}}:{}),rules:{actionsPerTurn:2,recovery:'Used cards enter FIFO queue; oldest one returns at turn end; unused ready cards persist.',phases:{approach:{progressGoal:3},strike:{lootGoal:4,rescueGoal:3,convoyDeadline:5,convoyRetreatPerTurn:1,pinBlocksConvoyRetreat:true},retreat:{progressGoal:6,runProgressWithLoot:2,runProgressWithoutLoot:3}},turnEndOrder:['player damage','companion damage and convoy movement during strike','pin -1','alarm +1 capped at 6','clear both shields','restore 2 actions','turn +1','recover oldest waiting card','check player death'],damage:'max(0, base + floor(alarm/3) - block); base: approach guards>0 ? 1 : 0; strike 1+ceil(guards/2); retreat 2',arrival:'Escape progress 6 ends encounter immediately, with no additional enemy hit.'},metrics:metrics(r),analysisNotes:['Events record committed game actions, not unconfirmed previews or taps.','Timestamps are wall-clock times and include interruptions; do not treat them as measured thinking time.','Legal alternatives and immediate outcomes are recorded, not proof of which long-term strategy is optimal.','Unused cards, unused actions and partial success do not establish player intent, confusion or a balance defect by themselves.','For partial coverage, do not reconstruct missing decisions or compare recorded damage with whole-run totals.']};}
export function compactReport(r){const full=exportReport(r),plain=s=>Object.fromEntries(Object.entries(s).filter(([k])=>k!=='log')),delta=(before,after)=>Object.fromEntries(Object.entries(plain(after)).filter(([k,v])=>JSON.stringify(v)!==JSON.stringify(before[k])));return {schema:'shanfara-run-compact-v1',instructions:'Start with initial. Each event.changes patches the preceding state to reconstruct its after-state. Each available[].changes patches that same event before-state, independently. Arrays replace whole arrays. Only redundant narration logs are omitted; actions, choices and game-state changes are preserved.',runId:r.runId,rulesVersion:r.rulesVersion,build:full.build,coverage:r.coverage,coverageNote:r.coverageNote,tutorial:r.tutorial,startedAt:r.startedAt,recordingStartedAt:r.recordingStartedAt,endedAt:r.endedAt,initial:plain(r.initial),final:plain(r.final),rules:full.rules,cardDefinitions:cards,metrics:full.metrics,...(full.relicDefinitions?{relicDefinitions:full.relicDefinitions,campaignRules:full.campaignRules}:{}),analysisNotes:full.analysisNotes,events:r.events.map(e=>({index:e.index,at:e.at,action:e.action,label:e.label,changes:delta(e.before,e.after),incomingBefore:e.incomingBefore,incomingAfter:e.incomingAfter,available:e.available.map(o=>({action:o.action,label:o.label,changes:delta(e.before,o.after),incomingDamage:o.incomingDamage}))}))};}
export function reportText(r){return `حلّل تقرير هذه الجولة من لعبة الشنفرى، وأجب بالعربية.\nقيّم وضوح القرارات وتنوع الاستراتيجيات وتوازن البطاقات، مع الاستشهاد بأرقام الحركات. فرّق بين ملاحظات مؤكدة وفرضيات تحتاج اختبارًا. لا تفترض نية اللاعب أو سبب قراراته، ولا تصف خيارًا بأنه مهيمن دون فحص عواقبه اللاحقة. اقترح أهم ثلاثة تعديلات فقط.\n\nSHANFARA_RUN_REPORT_V1\n${JSON.stringify(compactReport(r))}`;}
